public with sharing class RecordSearchService {

    public class SearchException extends Exception {}

    private static final Integer MAX_ROWS_LIMIT = 200;

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        // ---- maxRows validation ----
        if (maxRows == null || maxRows < 1 || maxRows > MAX_ROWS_LIMIT) {
            throw new SearchException('maxRows must be between 1 and ' + MAX_ROWS_LIMIT + '.');
        }

        // ---- fields validation ----
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('At least one field must be requested.');
        }

        // ---- object existence + read access ----
        if (String.isBlank(objectApiName)) {
            throw new SearchException('Object API name is required.');
        }
        Schema.SObjectType sobjectType;
        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        String requestedObjectKey = normalize(objectApiName);
        for (String key : globalDescribe.keySet()) {
            if (normalize(key) == requestedObjectKey) {
                sobjectType = globalDescribe.get(key);
                break;
            }
        }
        if (sobjectType == null) {
            throw new SearchException('Object "' + objectApiName + '" does not exist.');
        }
        Schema.DescribeSObjectResult objDescribe = sobjectType.getDescribe();
        if (!objDescribe.isAccessible()) {
            throw new SearchException('The running user cannot read object "' + objectApiName + '".');
        }

        // ---- field describe map (case-insensitive keys) ----
        Map<String, Schema.SObjectField> fieldMap = new Map<String, Schema.SObjectField>();
        for (Schema.SObjectField f : objDescribe.fields.getMap().values()) {
            fieldMap.put(normalize(f.getDescribe().getName()), f);
        }

        // ---- validate and resolve SELECT fields ----
        Set<String> selectFields = new Set<String>();
        for (String fieldName : fields) {
            if (String.isBlank(fieldName)) {
                throw new SearchException('Field names must not be blank.');
            }
            String key = normalize(fieldName);
            if (!fieldMap.containsKey(key)) {
                throw new SearchException('Field "' + fieldName + '" is not a field of ' + objectApiName + '.');
            }
            Schema.DescribeFieldResult fd = fieldMap.get(key).getDescribe();
            if (!fd.isAccessible()) {
                throw new SearchException('The running user cannot read field "' + fieldName + '".');
            }
            selectFields.add(fd.getName());
        }

        // ---- validate and resolve filters ----
        String whereClause = '';
        if (filters != null && !filters.isEmpty()) {
            List<String> conditions = new List<String>();
            for (String filterKey : filters.keySet()) {
                if (String.isBlank(filterKey)) {
                    throw new SearchException('Filter field names must not be blank.');
                }
                String key = normalize(filterKey);
                if (!fieldMap.containsKey(key)) {
                    throw new SearchException('Filter field "' + filterKey + '" is not a field of ' + objectApiName + '.');
                }
                Schema.DescribeFieldResult fd = fieldMap.get(key).getDescribe();
                if (!fd.isFilterable()) {
                    throw new SearchException('Field "' + filterKey + '" cannot be used in a filter.');
                }
                if (!fd.isAccessible()) {
                    throw new SearchException('The running user cannot read field "' + filterKey + '".');
                }
                String bindVarName = 'filterValue' + conditions.size();
                conditions.add(fd.getName() + ' = :' + bindVarName);
            }
            whereClause = ' WHERE ' + String.join(conditions, ' AND ');
        }

        // ---- validate and resolve ORDER BY ----
        String orderByClause = '';
        if (orderByField != null && !String.isBlank(orderByField)) {
            String key = normalize(orderByField);
            if (!fieldMap.containsKey(key)) {
                throw new SearchException('Order-by field "' + orderByField + '" is not a field of ' + objectApiName + '.');
            }
            Schema.DescribeFieldResult fd = fieldMap.get(key).getDescribe();
            if (!fd.isSortable()) {
                throw new SearchException('Field "' + orderByField + '" cannot be used for ordering.');
            }
            if (!fd.isAccessible()) {
                throw new SearchException('The running user cannot read field "' + orderByField + '".');
            }
            orderByClause = ' ORDER BY ' + fd.getName() + ' ASC';
        }

        // ---- build query ----
        List<String> orderedSelect = new List<String>(selectFields);
        orderedSelect.sort();
        String query = 'SELECT Id, ' + String.join(orderedSelect, ', ')
            + ' FROM ' + objDescribe.getName()
            + whereClause
            + orderByClause
            + ' LIMIT :maxRows';

        // ---- bind values safely (no string-literal interpolation) ----
        Map<String, Object> binds = new Map<String, Object>();
        if (filters != null && !filters.isEmpty()) {
            Integer i = 0;
            for (String filterKey : filters.keySet()) {
                String key = normalize(filterKey);
                Schema.DescribeFieldResult fd = fieldMap.get(key).getDescribe();
                binds.put('filterValue' + i, convertBindValue(fd, filters.get(filterKey)));
                i++;
            }
        }

        // queryWithBinds prevents SOQL injection for values; the class is "with sharing",
        // so record sharing is enforced. Fields were vetted via isAccessible() above.
        return Database.queryWithBinds(query, binds, AccessLevel.USER_MODE);
    }

    private static String normalize(String name) {
        return name == null ? '' : name.trim().toLowerCase();
    }

    /**
     * Coerces the incoming value to the type expected by the target field so that
     * bind variables serialize correctly (e.g. Id strings, Decimal, Date).
     * Returns null untouched, which SOQL treats as an equality-to-null check.
     */
    private static Object convertBindValue(Schema.DescribeFieldResult fd, Object value) {
        if (value == null) {
            return null;
        }
        Schema.DisplayType fieldType = fd.getType();
        try {
            if (fieldType == Schema.DisplayType.BOOLEAN) {
                return (Boolean) value;
            }
            if (fieldType == Schema.DisplayType.STRING
                || fieldType == Schema.DisplayType.PICKLIST
                || fieldType == Schema.DisplayType.MULTIPICKLIST
                || fieldType == Schema.DisplayType.TEXTAREA
                || fieldType == Schema.DisplayType.EMAIL
                || fieldType == Schema.DisplayType.PHONE
                || fieldType == Schema.DisplayType.URL) {
                return String.valueOf(value);
            }
            if (fieldType == Schema.DisplayType.ID
                || fieldType == Schema.DisplayType.REFERENCE) {
                return value instanceof Id ? (Id) value : Id.valueOf(String.valueOf(value));
            }
            if (fieldType == Schema.DisplayType.INTEGER) {
                return Integer.valueOf(String.valueOf(value));
            }
            if (fieldType == Schema.DisplayType.DOUBLE
                || fieldType == Schema.DisplayType.CURRENCY
                || fieldType == Schema.DisplayType.PERCENT) {
                return Decimal.valueOf(String.valueOf(value));
            }
            if (fieldType == Schema.DisplayType.DATE) {
                return value instanceof Date ? (Date) value : Date.valueOf(String.valueOf(value));
            }
            if (fieldType == Schema.DisplayType.DATETIME) {
                return value instanceof DateTime ? (DateTime) value : DateTime.valueOf(String.valueOf(value));
            }
        } catch (Exception e) {
            throw new SearchException('Filter value is not valid for field "' + fd.getName() + '": ' + e.getMessage());
        }
        return value;
    }
}
