public with sharing class ContactLookupAction {

    public class Request {
        @InvocableVariable(required=true label='Email' description='Email address to look up')
        public String email;
    }

    public class Result {
        @InvocableVariable(label='Contact Id' description='Id of the matching contact')
        public Id contactId;
        @InvocableVariable(label='Found' description='Whether a matching contact was found')
        public Boolean found;
    }

    @InvocableMethod(
        label='Find Contact by Email'
        description='Finds an existing contact by email (case-insensitive, trimmed). Returns the contact with the earliest CreatedDate when multiple match.'
    )
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();

        // Collect normalized (trimmed) emails; case handled via SOQL case-insensitive comparison.
        Set<String> normalizedEmails = new Set<String>();
        List<String> normalizedInputs = new List<String>();
        for (Request req : requests) {
            String normalized = req == null || req.email == null ? null : req.email.trim();
            normalizedInputs.add(normalized);
            if (String.isNotBlank(normalized)) {
                normalizedEmails.add(normalized);
            }
        }

        // Map each normalized email to the contact with the earliest CreatedDate.
        Map<String, Id> emailToContactId = new Map<String, Id>();

        if (!normalizedEmails.isEmpty()) {
            // Single SOQL query for the whole batch.
            // Email comparison in SOQL is case-insensitive for emails; results ordered
            // by CreatedDate so the first seen per email is the earliest created.
            for (Contact c : [
                SELECT Id, Email
                FROM Contact
                WHERE Email IN :normalizedEmails
                WITH USER_MODE
                ORDER BY CreatedDate ASC
            ]) {
                String key = c.Email == null ? null : c.Email.trim();
                if (key != null && !emailToContactId.containsKey(key)) {
                    emailToContactId.put(key, c.Id);
                }
            }
        }

        for (String normalized : normalizedInputs) {
            Result res = new Result();
            if (String.isNotBlank(normalized) && emailToContactId.containsKey(normalized)) {
                res.contactId = emailToContactId.get(normalized);
                res.found = true;
            } else {
                res.contactId = null;
                res.found = false;
            }
            results.add(res);
        }

        return results;
    }
}
