        // Losing and re-winning means the opportunity is "newly won" again on the second update.
        Opportunity o = makeOpp(null, WON, Date.today());
        insert o;
        Test.startTest();
        Opportunity lost = new Opportunity(Id = o.Id, StageName = 'Negotiation');
        update lost;
        Opportunity rewinned = new Opportunity(Id = o.Id, StageName = WON);
        update rewinned;
        Test.stopTest();
        Opportunity saved = [SELECT NextStep FROM Opportunity WHERE Id = :o.Id];
