    }

    // ---------- bulk safety ----------

    @isTest
    static void bulkTwoHundredNewlyWonIsBulkSafe() {
        // 200 accounts so the account rating query has real work to do.
        List<Account> accounts = new List<Account>();
        for (Integer i = 0; i < 200; i++) {
