public inherited sharing class PicklistService {

    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;
    }

    public class PicklistServiceException extends Exception {}

    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName) || String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Object and field API names must not be null or blank.');
        }

        Schema.SObjectType sObjectType = Schema.getGlobalDescribe().get(objectApiName.toLowerCase());
        if (sObjectType == null) {
            throw new PicklistServiceException('Object not found: ' + objectApiName);
        }

        Schema.SObjectField sObjectField = sObjectType.getDescribe().fields.getMap().get(fieldApiName.toLowerCase());
        if (sObjectField == null) {
            throw new PicklistServiceException(
                'Field ' + fieldApiName + ' not found on object ' + objectApiName);
        }

        Schema.DescribeFieldResult fieldResult = sObjectField.getDescribe();

        if (fieldResult.getType() != Schema.DisplayType.PICKLIST
                && fieldResult.getType() != Schema.DisplayType.MULTIPICKLIST) {
            throw new PicklistServiceException(
                'Field ' + fieldApiName + ' is not a picklist or multi-select picklist.');
        }

        List<Option> options = new List<Option>();
        for (Schema.PicklistEntry entry : fieldResult.getPicklistValues()) {
            if (entry.isActive()) {
                Option option = new Option();
                option.value = entry.getValue();
                option.label = entry.getLabel();
                option.isDefault = entry.isDefaultValue();
                options.add(option);
            }
        }
        return options;
    }
}
