    public List<Opportunity> selectTopOpenByAccountIds(Set<Id> accountIds, Integer maxRecords) {
        fflib_QueryFactory queryFactory = newQueryFactory();
        queryFactory.setCondition('AccountId IN :accountIds AND IsClosed = false');
        // Extend the selector's standard field list with the parent Account Name
        queryFactory.addFieldRelationship('Account', 'Name');

        String soql = queryFactory.toSOQL();
        // Remove any default ordering/limit the factory may have appended so we
        // can impose the required ordering and row cap in a single clause set.
        Integer orderByIndex = soql.indexOfIgnoreCase(' ORDER BY');
        if (orderByIndex >= 0) {
            soql = soql.substring(0, orderByIndex);
        }

        // Highest Amount first; nulls (no Amount) after all others; ties by
        // earliest CloseDate. Limited to maxRecords rows in one query.
        soql += ' ORDER BY Amount DESC NULLS LAST, CloseDate ASC';
        soql += ' LIMIT ' + maxRecords;

        return (List<Opportunity>) Database.query(soql);
    }
