        return new List<Schema.SObjectField>{
            Account.Id,
            Account.Name,
            Account.Industry,
            Account.AnnualRevenue,
            Account.Rating
        };
    }

    public override String getQuery(Map<Id, Set<String>> relatedFieldSelectors) {
        String baseQuery = super.getQuery(relatedFieldSelectors);
        // Dynamically add every field in the Credit_Review field set (no hard-coding)
        List<String> fieldSetFields = new List<String>();
        for (Schema.FieldSetMember member : SObjectType.Account.FieldSets.Credit_Review.getFields()) {
            fieldSetFields.add(member.getFieldPath());
        }
        if (fieldSetFields.isEmpty()) {
            return baseQuery;
        }
        // Insert the field set fields into the SELECT clause before the FROM keyword
        Integer fromIndex = baseQuery.toUpperCase().lastIndexOf(' FROM ');
        return baseQuery.substring(0, fromIndex) + ',' + String.join(fieldSetFields, ',') + baseQuery.substring(fromIndex);
    }

    public List<Account> selectById(Set<Id> accountIds) {
        return (List<Account>) selectSObjectsById(accountIds);
    }

    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        // Base query built by this selector (field list + Credit_Review field set, USER_MODE)
        String baseQuery = getQuery(new Map<Id, Set<String>>());
        // Build the Contacts subquery from ContactsSelector so it uses that selector's fields
        ContactsSelector contactsSelector = new ContactsSelector();
        String contactSubQuery = contactsSelector.newQueryFactory(false).toSOQLSubQuery();
        // Inject the subquery into the SELECT clause before the FROM keyword
        Integer fromIndex = baseQuery.toUpperCase().lastIndexOf(' FROM ');
        String soql = baseQuery.substring(0, fromIndex) + ', ' + contactSubQuery + baseQuery.substring(fromIndex)
            + ' WHERE Id IN :accountIds' + getOrderBySuffix();
        return (List<Account>) Database.query(soql);
    }

    private String getOrderBySuffix() {
        String orderBy = getOrderBy();
        return String.isBlank(orderBy) ? '' : ' ORDER BY ' + orderBy;
    }
