```apex
public inherited sharing class AccountOnboardingService {

    public static List<Account> createAccountsWithContacts(Map<String, List<String>> contactLastNamesByAccountName) {
        if (contactLastNamesByAccountName == null || contactLastNamesByAccountName.isEmpty()) {
            return new List<Account>();
        }

        // Order matters: fflib_SObjectUnitOfWork commits DML in the order the
        // SObjectTypes are listed, so Accounts must precede Contacts to allow
        // the Contact.AccountId relationships to be resolved by the UoW.
        fflib_SObjectUnitOfWork uow = new fflib_SObjectUnitOfWork(
            new List<SObjectType> {
                Account.SObjectType,
                Contact.SObjectType
            }
        );

        List<Account> newAccounts = new List<Account>();

        for (String accountName : contactLastNamesByAccountName.keySet()) {
            if (accountName == null) {
                continue;
            }
            Account acc = new Account(Name = accountName);
            uow.registerNew(acc);
            newAccounts.add(acc);

            List<String> lastNames = contactLastNamesByAccountName.get(accountName);
            if (lastNames == null) {
                continue;
            }
            for (String lastName : lastNames) {
                if (lastName == null) {
                    continue;
                }
                // The UoW will populate Contact.AccountId with the new
                // Account's Id once the Account has been inserted.
                Contact con = new Contact(LastName = lastName);
                uow.registerNew(con, Contact.AccountId, acc);
            }
        }

        uow.commitWork();

        return newAccounts;
    }
}
