public with sharing class DealEventPublisher {

    /**
     * Publishes one Deal_Stage_Change__e platform event per Opportunity and
     * returns the publish results in the same order as the input list.
     *
     * Deviation from the originally stated approach: EventBus.publish is NOT
     * called once per opportunity inside the loop. Each EventBus.publish call
     * counts as a DML statement, and with a batch of 200 opportunities that
     * would hit the 150 DML statement-per-transaction limit. Instead, all
     * events are collected and published in a single EventBus.publish call,
     * which returns one SaveResult per event, in the same order as the events
     * (and therefore the input list). This preserves exact per-event failure
     * reporting while staying bulk-safe.
     */
    public static List<Database.SaveResult> publishStageChanges(List<Opportunity> opportunities) {
        if (opportunities == null || opportunities.isEmpty()) {
            return new List<Database.SaveResult>();
        }

        List<Deal_Stage_Change__e> events = new List<Deal_Stage_Change__e>();
        for (Opportunity opp : opportunities) {
            events.add(new Deal_Stage_Change__e(
                Opportunity_Id__c = opp.Id,
                Stage__c = opp.StageName,
                Amount__c = opp.Amount
            ));
        }

        // Single DML statement; SaveResults are returned in the same order
        // as the events, i.e. the same order as the input list.
        return EventBus.publish(events);
    }
}
