import { LightningElement, api, wire } from 'lwc';
import { getRecord } from 'lightning/uiRecordApi';
import NAME_FIELD from '@salesforce/schema/Account.Name';
import INDUSTRY_FIELD from '@salesforce/schema/Account.Industry';
import REVENUE_FIELD from '@salesforce/schema/Account.AnnualRevenue';
import OWNER_NAME_FIELD from '@salesforce/schema/Account.Owner.Name';

const FIELDS = [NAME_FIELD];
const OPTIONAL_FIELDS = [INDUSTRY_FIELD, REVENUE_FIELD, OWNER_NAME_FIELD];

export default class AccountHeader extends LightningElement {
    @api recordId;

    name;
    industry;
    annualRevenue;
    ownerName;
    error;

    @wire(getRecord, {
        recordId: '$recordId',
        fields: FIELDS,
        optionalFields: OPTIONAL_FIELDS
    })
    wiredRecord({ data, error }) {
        if (data) {
            this.name = data.fields.Name.value;
            this.industry = data.fields.Industry?.value ?? null;
            this.annualRevenue = data.fields.AnnualRevenue?.value ?? null;
            this.ownerName = data.fields.Owner?.displayValue
                ? data.fields.Owner.displayValue
                : data.fields.Owner?.value?.fields?.Name?.value ?? null;
            this.error = undefined;
        } else if (error) {
            this.error = error;
            this.name = undefined;
            this.industry = undefined;
            this.annualRevenue = undefined;
            this.ownerName = undefined;
        }
    }

    get hasRecord() {
        return !this.error && this.name !== undefined;
    }
}
