import { LightningElement, api } from 'lwc';

export default class AccountContactList extends LightningElement {
    _contacts;

    @api
    get contacts() {
        return this._contacts;
    }

    set contacts(value) {
        this._contacts = Array.isArray(value) ? [...value] : value;
    }

    get hasContacts() {
        return Array.isArray(this.contacts) && this.contacts.length > 0;
    }

    get sortedContacts() {
        if (!this.hasContacts) {
            return [];
        }
        return this.contacts.slice().sort(function (a, b) {
            var aName = a.Name == null ? '' : String(a.Name);
            var bName = b.Name == null ? '' : String(b.Name);
            return aName.localeCompare(bName);
        });
    }

    get contactCountLabel() {
        var count = this.sortedContacts.length;
        return count === 1 ? '1 contact' : count + ' contacts';
    }
}
