    get isReady() {
        return this.state === STATES.READY;
    }

    get isError() {
        return this.state === STATES.ERROR;
    }

    get hasOpportunities() {
        return this.opportunities.length > 0;
    }

    get isEmpty() {
        return this.opportunities.length === 0;
    }
