public class GiftImportService {

    /**
     * Imports one-off web gifts through NPSP's Data Import engine (BDI).
     *
     * One npsp__DataImport__c record is staged per gift and left in the org as
     * the audit trail of what was imported. NPSP's Apex API for data import is
     * invoked synchronously, in the same transaction, so the org's
     * npsp__Data_Import_Settings__c drive contact matching (first name +
     * last name + email), household creation and donation processing.
     */
    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();
        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // Stage one Data Import record per gift, preserving input order.
        // These rows remain in the org as the audit trail of the import.
        List<npsp__DataImport__c> stagedImports = new List<npsp__DataImport__c>();
        for (WebGift gift : gifts) {
            stagedImports.add(new npsp__DataImport__c(
                npsp__Contact1_Firstname__c = gift.firstName,
                npsp__Contact1_Lastname__c = gift.lastName,
                npsp__Contact1_Personal_Email__c = gift.email,
                npsp__Donation_Amount__c = gift.amount,
                npsp__Donation_Date__c = gift.giftDate,
                npsp__Donation_Donor__c = 'Contact1'
            ));
        }

        // Insert the staging rows. NPSP writes Status, the imported
        // Contact/Opportunity Ids and failure information back onto them.
        insert stagedImports;

        // Run NPSP's BDI engine synchronously, in this transaction, applying
        // the org's Data Import settings. A batch-level failure must not stop
        // the whole call: failed rows are reported individually below.
        try {
            runDataImportBatch(stagedImports);
        } catch (Exception e) {
            System.debug(LoggingLevel.ERROR,
                'GiftImportService: BDI processBatch exception: ' + e.getMessage());
        }

        // Re-query the staged rows for the results NPSP wrote back to them.
        Set<Id> stagedIds = new Set<Id>();
        for (npsp__DataImport__c di : stagedImports) {
            stagedIds.add(di.Id);
        }
        Map<Id, npsp__DataImport__c> processed = new Map<Id, npsp__DataImport__c>([
            SELECT Id,
                   npsp__Status__c,
                   npsp__FailureInformation__c,
                   npsp__Contact1Imported__c,
                   npsp__DonationImported__c
            FROM npsp__DataImport__c
            WHERE Id IN :stagedIds
        ]);

        // Build one result per gift, in input order.
        for (npsp__DataImport__c di : stagedImports) {
            ImportResult result = new ImportResult();
            npsp__DataImport__c row = processed.get(di.Id);
            String status = (row == null) ? null : row.npsp__Status__c;

            if ('Imported'.equals(status)) {
                result.success = true;
                result.contactId = (row != null) ? row.npsp__Contact1Imported__c : null;
                result.opportunityId = (row != null) ? row.npsp__DonationImported__c : null;
            } else {
                result.success = false;
                String failureInfo = (row == null) ? null : row.npsp__FailureInformation__c;
                result.errorMessage = String.isNotBlank(failureInfo)
                    ? failureInfo
                    : 'NPSP Data Import did not import this row (status: '
                        + (status == null ? 'unprocessed' : status) + ')';
            }
            results.add(result);
        }

        return results;
    }

    /**
     * Invokes NPSP's synchronous BDI batch processor (DataImportAPI.processBatch)
     * with the second argument set so NPSP applies the org's Data Import
     * settings to the staged records.
     *
     * The class is resolved dynamically because NPSP's package namespace is not
     * statically referenceable from Apex in all installs; both the namespaced
     * and unnamespaced class names are tried. If a test double with the same
     * signature is present it will be found first by Type.forName.
     */
    @TestVisible
    private static void runDataImportBatch(List<npsp__DataImport__c> stagedImports) {
        List<String> candidateClassNames = new List<String>{
            'npsp.DataImportAPI',
            'DataImportAPI'
        };

        for (String className : candidateClassNames) {
            Type apiType = Type.forName(className);
            if (apiType == null) {
                continue;
            }
            Object apiInstance = apiType.newInstance();
            for (System.Method m : apiType.getMethods()) {
                if ('processBatch'.equals(m.getName())
                        && m.getParameterTypes().size() == 2) {
                    List<Object> args = new List<Object>{ stagedImports, true };
                    m.invoke(apiInstance, args);
                    return;
                }
            }
        }

        throw new GiftImportException(
            'NPSP Data Import API class (DataImportAPI.processBatch) was not found in this org.');
    }

    public class GiftImportException extends Exception {}
}
