/**
 * HouseholdService
 * Creates a single NPSP Household Account and associates the given new
 * Contacts with it. The first Contact in the list becomes the household's
 * primary contact (Account.npe01__One2OneContact__c).
 *
 * The Account is created with the NPSP Household Account record type. The
 * Account's Name is only seeded with a temporary value to satisfy the
 * standard Account required-field rule; NPSP's household naming and greeting
 * logic runs from the Contact triggers once the members are inserted, and it
 * overwrites the household name itself. We never hard-code record type Ids.
 */
public with sharing class HouseholdService {

    /**
     * Creates one NPSP Household Account containing all the given Contacts.
     *
     * @param members new Contacts (no Id, no AccountId) to place in the household
     * @return       the Id of the new household Account
     * @throws IllegalArgumentException if members is null or empty
     */
    public static Id createHousehold(List<Contact> members) {
        // ---- Validation -----------------------------------------------------
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException(
                'HouseholdService.createHousehold requires a non-empty list of Contacts.');
        }

        for (Contact c : members) {
            if (c.Id != null) {
                throw new IllegalArgumentException(
                    'All Contacts must be new records (no Id set).');
            }
            if (c.AccountId != null) {
                throw new IllegalArgumentException(
                    'All Contacts must be new records (no AccountId set).');
            }
        }

        // ---- Resolve the Household Account record type (no hard-coded Ids) --
        Id householdRecordTypeId = getHouseholdRecordTypeId();

        // ---- Create the household Account -----------------------------------
        // Account.Name is a standard required field, so seed a temporary value;
        // NPSP's household naming trigger (fired by the Contact inserts below)
        // sets the real household name from its members.
        Account household = new Account(
            Name = 'Temporary Household Name',
            RecordTypeId = householdRecordTypeId
        );

        try {
            insert household;
        } catch (DmlException e) {
            throw new IllegalArgumentException(
                'Unable to create the household Account: ' + e.getMessage());
        }

        // ---- Create the household members -----------------------------------
        // Inserting Contacts linked to the household Account fires NPSP's
        // Contact triggers, which generate the household name and greetings.
        List<Contact> toInsert = new List<Contact>();
        for (Contact c : members) {
            Contact newContact = c.clone(false);
            newContact.AccountId = household.Id;
            toInsert.add(newContact);
        }

        try {
            insert toInsert;
        } catch (DmlException e) {
            // Roll back the household so no empty/extra account is left behind.
            delete household;
            throw new IllegalArgumentException(
                'Unable to create the household Contacts: ' + e.getMessage());
        }

        // ---- Set the primary contact -----------------------------------------
        // NPSP stores the household's primary contact in npe01__One2OneContact__c.
        Account primaryUpdate = new Account(
            Id = household.Id,
            npe01__One2OneContact__c = toInsert[0].Id
        );

        try {
            update primaryUpdate;
        } catch (DmlException e) {
            // Do not leave a broken household behind; remove contacts + account.
            delete toInsert;
            delete household;
            throw new IllegalArgumentException(
                'Unable to set the household primary contact: ' + e.getMessage());
        }

        return household.Id;
    }

    /**
     * Looks up the Household Account record type Id by DeveloperName at runtime,
     * so no record type Id is ever hard-coded and the code is org-portable.
     */
    private static Id getHouseholdRecordTypeId() {
        Id rtId = null;
        for (RecordType rt : [
            SELECT Id
            FROM RecordType
            WHERE SobjectType = 'Account'
              AND DeveloperName = 'HH_Account'
            LIMIT 1
        ]) {
            rtId = rt.Id;
        }
        if (rtId == null) {
            throw new IllegalArgumentException(
                'Household Account record type (DeveloperName = HH_Account) was not found in this org.');
        }
        return rtId;
    }
}
