public with sharing class FamilyService {

    private static final String TYPE_PARENT = 'Parent';
    private static final String STATUS_CURRENT = 'Current';

    /**
     * Links parents to children by creating the child-side NPSP Relationship
     * (Contact = child, RelatedContact = parent, Type = Parent, Status = Current).
     * NPSP's reciprocal relationship logic (List Setting method + Relationship
     * Lookup: Male Son / Female Daughter / Neutral Child) automatically creates
     * the parent-side record (Son, Daughter or Child), so each pair ends up with
     * exactly one relationship record in each direction.
     *
     * Pairs where any relationship already exists between the two contacts (in
     * either direction) are skipped so the import can be re-run safely.
     *
     * Limits: at most 1 SOQL query and 1 DML statement for any input size,
     * including 200 pairs in one call.
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Collect valid pairs, skipping null/blank ids.
        Set<Id> allContactIds = new Set<Id>();
        List<Id> childIds = new List<Id>();
        List<Id> parentIds = new List<Id>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null) {
                continue;
            }
            childIds.add(childId);
            parentIds.add(parentId);
            allContactIds.add(childId);
            allContactIds.add(parentId);
        }

        if (childIds.isEmpty()) {
            return;
        }

        // Single SOQL: fetch every relationship touching any involved contact,
        // then match exact pairs in memory (either direction).
        Map<Id, Set<Id>> relatedByContact = new Map<Id, Set<Id>>();
        for (npe4__Relationship__c rel : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :allContactIds
              AND npe4__RelatedContact__c IN :allContactIds
        ]) {
            addRelated(relatedByContact, rel.npe4__Contact__c, rel.npe4__RelatedContact__c);
            addRelated(relatedByContact, rel.npe4__RelatedContact__c, rel.npe4__Contact__c);
        }

        // Build child-side records only for pairs with no existing relationship.
        List<npe4__Relationship__c> toInsert = new List<npe4__Relationship__c>();
        for (Integer i = 0; i < childIds.size(); i++) {
            Id childId = childIds[i];
            Id parentId = parentIds[i];
            if (childId == parentId) {
                continue; // a contact cannot be its own parent
            }
            Set<Id> relatedToChild = relatedByContact.get(childId);
            if (relatedToChild != null && relatedToChild.contains(parentId)) {
                continue;
            }
            toInsert.add(new npe4__Relationship__c(
                npe4__Contact__c = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c = TYPE_PARENT,
                npe4__Status__c = STATUS_CURRENT
            ));
        }

        if (!toInsert.isEmpty()) {
            // One DML. NPSP's Relationship trigger creates the reciprocal record
            // (Son / Daughter / Child per the Relationship Lookup) automatically.
            insert toInsert;
        }
    }

    private static void addRelated(Map<Id, Set<Id>> relatedByContact, Id contactId, Id relatedId) {
        Set<Id> related = relatedByContact.get(contactId);
        if (related == null) {
            related = new Set<Id>();
            relatedByContact.put(contactId, related);
        }
        related.add(relatedId);
    }
}
