@IsTest
private class TA_Opportunity_GuardAmountDecreaseTest {

    private static final String ERROR_MESSAGE = 'Amount cannot be reduced by more than half in a single update.';

    private static Opportunity buildOpportunity(Id recordId, Decimal amount) {
        return new Opportunity(
            Id = recordId,
            Amount = amount
        );
    }

    @IsTest
    private static void testReductionOfMoreThanHalfIsRejected() {
        Id fakeId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity newOpp = buildOpportunity(fakeId, 499);
        Opportunity oldOpp = buildOpportunity(fakeId, 1000);

        Test.startTest();
        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(
            new List<Opportunity>{ newOpp },
            new List<Opportunity>{ oldOpp }
        );
        Test.stopTest();

        System.assertEquals(true, newOpp.hasErrors(), 'A reduction of more than half must be rejected.');
        System.assertEquals(1, newOpp.getErrors().size(), 'Exactly one error is expected.');
        System.assertEquals(
            ERROR_MESSAGE,
            newOpp.getErrors()[0].getMessage(),
            'The error message must match the action constant.'
        );
    }

    @IsTest
    private static void testReductionOfExactlyHalfIsAccepted() {
        Id fakeId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity newOpp = buildOpportunity(fakeId, 500);
        Opportunity oldOpp = buildOpportunity(fakeId, 1000);

        Test.startTest();
        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(
            new List<Opportunity>{ newOpp },
            new List<Opportunity>{ oldOpp }
        );
        Test.stopTest();

        System.assertEquals(false, newOpp.hasErrors(), 'A reduction of exactly half must be accepted.');
    }

    @IsTest
    private static void testIncreaseIsAccepted() {
        Id fakeId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity newOpp = buildOpportunity(fakeId, 1500);
        Opportunity oldOpp = buildOpportunity(fakeId, 1000);

        Test.startTest();
        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(
            new List<Opportunity>{ newOpp },
            new List<Opportunity>{ oldOpp }
        );
        Test.stopTest();

        System.assertEquals(false, newOpp.hasErrors(), 'An increase must be accepted.');
    }

    @IsTest
    private static void testNullPreviousAmountIsAccepted() {
        Id fakeId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity newOpp = buildOpportunity(fakeId, 10);
        Opportunity oldOpp = buildOpportunity(fakeId, null);

        Test.startTest();
        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(
            new List<Opportunity>{ newOpp },
            new List<Opportunity>{ oldOpp }
        );
        Test.stopTest();

        System.assertEquals(false, newOpp.hasErrors(), 'A null previous Amount must be accepted without exception.');
    }

    @IsTest
    private static void testMixedRecordsOnlyViolatorsGetErrors() {
        Id id1 = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id id2 = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id id3 = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id id4 = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        // id1: violation, id2: exactly half (ok), id3: increase (ok), id4: violation.
        Opportunity new1 = buildOpportunity(id1, 100);
        Opportunity new2 = buildOpportunity(id2, 500);
        Opportunity new3 = buildOpportunity(id3, 2000);
        Opportunity new4 = buildOpportunity(id4, 1);
        Opportunity old1 = buildOpportunity(id1, 1000);
        Opportunity old2 = buildOpportunity(id2, 1000);
        Opportunity old3 = buildOpportunity(id3, 1000);
        Opportunity old4 = buildOpportunity(id4, 1000);

        List<Opportunity> triggerNew = new List<Opportunity>{ new1, new2, new3, new4 };
        List<Opportunity> triggerOld = new List<Opportunity>{ old1, old2, old3, old4 };

        Test.startTest();
