public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {
    /**
     * Creates an "Amount changed" Task for each Opportunity whose Amount changed on update.
     * The rounding action (TA_Opportunity_RoundAmount, Order 20) re-fires the trigger via a
     * second update in the same transaction; the static set below guarantees at most one
     * audit Task per Opportunity per transaction.
     */
    @TestVisible
    private static Set<Id> loggedOpportunityIds = new Set<Id>();

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Opportunity> newOpps = (List<Opportunity>) triggerNew;
        List<Opportunity> oldOpps = (List<Opportunity>) triggerOld;

        List<Task> tasks = new List<Task>();
        Map<Id, Opportunity> oldById = new Map<Id, Opportunity>(oldOpps);

        for (Opportunity opp : newOpps) {
            if (loggedOpportunityIds.contains(opp.Id)) {
                continue; // already audited in this transaction (recursion from rounding)
            }
            Opportunity oldOpp = oldById.get(opp.Id);
            if (oldOpp == null) {
                continue;
            }
            Decimal newAmount = opp.Amount;
            Decimal oldAmount = oldOpp.Amount;
            Boolean changed = (newAmount == null && oldAmount != null)
                || (newAmount != null && oldAmount == null)
                || (newAmount != null && oldAmount != null && newAmount != oldAmount);
            if (changed) {
                loggedOpportunityIds.add(opp.Id);
                tasks.add(new Task(
                    Subject = 'Amount changed',
                    WhatId = opp.Id,
                    Status = 'Completed'
                ));
            }
        }

        if (!tasks.isEmpty()) {
            insert tasks;
        }
    }
}
