/**
 * Before-insert Contact action: when a new contact has an Account and all four
 * mailing address fields are blank, copy the Account billing address into them.
 * Contacts without an Account, or with any mailing field filled in, are left
 * unchanged. Relies on TA_Contact_Queries.Service having run first (Order 1).
 */
public inherited sharing class TA_Contact_InheritMailingAddress implements TriggerAction.BeforeInsert {

    public void beforeInsert(List<SObject> triggerNew) {
        Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;
        for (Contact c : (List<Contact>) triggerNew) {
            if (c.AccountId == null || !accountsById.containsKey(c.AccountId)) {
                continue;
            }
            if (String.isBlank(c.MailingStreet)
                    && String.isBlank(c.MailingCity)
                    && String.isBlank(c.MailingPostalCode)
                    && String.isBlank(c.MailingCountry)) {
                Account acct = accountsById.get(c.AccountId);
                c.MailingStreet = acct.BillingStreet;
                c.MailingCity = acct.BillingCity;
                c.MailingPostalCode = acct.BillingPostalCode;
                c.MailingCountry = acct.BillingCountry;
            }
        }
    }
}
