/**
 * Before-insert Contact action: when a new contact has an Account and a blank
 * LeadSource, default it to the Account AccountSource. Contacts without an
 * Account are left unchanged. Relies on TA_Contact_Queries.Service having run
 * first (Order 1).
 */
public inherited sharing class TA_Contact_DefaultLeadSource implements TriggerAction.BeforeInsert {

    public void beforeInsert(List<SObject> triggerNew) {
        Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;
        for (Contact c : (List<Contact>) triggerNew) {
            if (c.AccountId == null || !accountsById.containsKey(c.AccountId)) {
                continue;
            }
            if (String.isBlank(c.LeadSource)) {
                c.LeadSource = accountsById.get(c.AccountId).AccountSource;
            }
        }
    }
}
